// In-memory ledger for the prototype.
//
// It follows the same contract as the PostgreSQL ledger in services/ledger:
// double entry, zero sum per asset, idempotency keys, no negative balances
// except the operator's issuance and custody accounts, an append-only log,
// and role-scoped handles. The error codes match the SQLSTATE codes there.
//
// Gameplay code is only ever given the `gameplay` handle. That handle cannot
// see or move external assets (test bitcoin) and cannot create game currency.

export class LedgerError extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'LedgerError';
    this.code = code;
  }
}

export const LEDGER_ASSETS = {
  // Sandbox bitcoin: generated by the built-in test chain, worth nothing.
  TBTC: { code: 'TBTC', class: 'external', minorUnits: 8, network: 'sandbox', label: 'test bitcoin' },
  // In-game currency: TR. Not legal tender of anywhere, and not a cryptocurrency. (10 October 2026: the owner
  // renamed the cowrie. A new arrival's money, which stands for £20, is 2,000 TR.)
  //
  // What the ledger holds did not change, and nothing in any save was rewritten: every amount is still the same
  // whole number it was. Only what that number is called changed. One ledger unit was a hundredth of a cowrie;
  // it is now half a TR, so the 4,000 units a new arrival was given are 2,000 TR and are still £20. Because no
  // stored number is touched, the change cannot be applied twice and cannot lose or make anyone a single unit.
  // (An account written before the change says its asset is 'CWR'; it is read as 'TR'.)
  TR: { code: 'TR', class: 'game', minorUnits: null, unitsPerWhole: 2, network: null, label: 'TR' },
};
export const LEGACY_ASSET_CODES = Object.freeze({ CWR: 'TR' });

// Ledger units in one TR. Write a price as `10 * TR`; never divide money by this except to show it.
export const TR = 2;
// The pound sterling of 1970 that the story speaks of: £20 are 2,000 TR.
export const TR_PER_POUND = 100;
// Ledger units as people read them: 4000 is "2,000", 20 is "10", 1 is "0.5".
export const trAmount = (n) => { const v = Math.round(Number(n) || 0); return (v / TR).toLocaleString('en-GB', { minimumFractionDigits: v % TR === 0 ? 0 : 1, maximumFractionDigits: 1 }); };
export const trText = (n) => `${trAmount(n)} TR`;
// The same number with no commas, for a box a number is typed into.
export const trPlain = (n) => String(Math.round(Number(n) || 0) / TR);
// What a number of TR a person types becomes in ledger units (null if it is not an amount).
export const trIn = (typed) => { const v = Number(typed); return Number.isFinite(v) ? Math.round(v * TR) : null; };
export const poundsOf = (n) => Math.round(Number(n) || 0) / TR / TR_PER_POUND;

export const LEDGER_KINDS = {
  transfer: 'game', wage: 'game', goods_purchase: 'game', land_purchase: 'game',
  government_fee: 'game', issuance: 'game', retirement: 'game',
  // the law and the hospital: money taken, money given back, a fine, a bill for treatment
  theft: 'game', restitution: 'game', fine: 'game', medical_fee: 'game',
  deposit: 'external', withdrawal_hold: 'external', withdrawal_release: 'external',
  withdrawal_settle: 'external',
  conversion: 'bridge', redemption_hold: 'bridge', redemption_release: 'bridge', redemption: 'bridge',
};

// What the ledger insists on for some kinds of transaction, whoever asks. The
// production ledger holds the same rules as data (migration 0003).
//   required  metadata that must be there      once      metadata values that may be paid for only once
//   any       at least one of these            payeeKinds who may be paid
export const LEDGER_KIND_RULES = Object.freeze({
  theft: Object.freeze({ required: ['crime'], any: [], once: ['crime'], payers: 1, payees: 1, payeeKinds: ['player'] }),
  restitution: Object.freeze({ required: ['crime', 'arrest'], any: [], once: [], payers: 1, payees: 1, payeeKinds: ['player', 'business', 'community'] }),
  fine: Object.freeze({ required: ['arrest', 'officer'], any: [], once: ['arrest'], payers: 1, payees: 2, payeeKinds: ['player', 'government'] }),
  medical_fee: Object.freeze({ required: [], any: ['quote', 'call'], once: ['quote', 'call'], payers: 1, payees: 1, payeeKinds: ['business', 'government'] }),
});
export const LEDGER_POLICY = Object.freeze({ fineGovernmentPartsPerHundred: 1 });
// The government's share of a fine after an arrest by a player constable: rounded up, never nothing, never more than the fine.
export const fineShares = (amount) => { const government = Math.min(amount, Math.max(1, Math.floor((amount * LEDGER_POLICY.fineGovernmentPartsPerHundred + 99) / 100))); return { government, constable: amount - government }; };

function ledgerHash(value) {
  // Small non-cryptographic hash; the production ledger uses SHA-256.
  const text = JSON.stringify(value);
  let h = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(16);
}

export function createLedger(saved) {
  const accounts = new Map();
  const byOwner = new Map();
  const transactions = [];
  const byKey = new Map();
  const paidOnce = new Map();      // "fine|arrest:A-1" -> the transaction that paid it
  let clock = () => 0;

  const ownerKey = (ownerKind, ownerId, purpose, asset) => `${ownerKind}|${ownerId}|${purpose}|${asset}`;

  function addAccount(ownerKind, ownerId, purpose, asset, allowNegative) {
    const key = ownerKey(ownerKind, ownerId, purpose, asset);
    if (byOwner.has(key)) return byOwner.get(key);
    const id = `acct-${String(accounts.size + 1).padStart(5, '0')}`;
    accounts.set(id, { id, ownerKind, ownerId, purpose, asset, allowNegative: !!allowNegative, balance: 0, entries: 0 });
    byOwner.set(key, id);
    return id;
  }

  function open(allowedClasses, ownerKind, ownerId, purpose, asset) {
    if (ownerKind === 'system') throw new LedgerError('NL004', 'system accounts are created at start-up only');
    const def = LEDGER_ASSETS[asset];
    if (!def) throw new LedgerError('NL005', `unknown asset ${asset}`);
    if (!allowedClasses.includes(def.class)) throw new LedgerError('NL004', `this role may not open accounts in ${asset}`);
    return addAccount(ownerKind, String(ownerId), purpose, asset, false);
  }

  const present = (meta, name) => typeof meta[name] === 'string' && meta[name] !== '';
  const subjectsOf = (kind, meta) => { const rule = LEDGER_KIND_RULES[kind]; return rule ? rule.once.filter((name) => present(meta, name)).map((name) => `${kind}|${name}:${meta[name]}`) : []; };

  // The rules of a kind: what it must say about itself, that it has not been paid before, and who is paid.
  function checkKind(kind, meta, legs) {
    const rule = LEDGER_KIND_RULES[kind];
    if (!rule) return;
    for (const name of rule.required) if (!present(meta, name)) throw new LedgerError('NL012', `a ${kind} transaction must say which ${name} it is for`);
    if (rule.any.length && !rule.any.some((name) => present(meta, name))) throw new LedgerError('NL012', `a ${kind} transaction must name one of: ${rule.any.join(', ')}`);
    for (const subject of subjectsOf(kind, meta)) if (paidOnce.has(subject)) throw new LedgerError('NL011', `a ${kind} has already been posted for ${subject.split('|')[1]}`);
    const debits = legs.filter((leg) => leg.amount < 0), credits = legs.filter((leg) => leg.amount > 0);
    if (debits.length > rule.payers || credits.length > rule.payees) throw new LedgerError('NL012', `a ${kind} transaction debits at most ${rule.payers} and credits at most ${rule.payees} accounts`);
    for (const leg of credits) { const account = accounts.get(leg.account); if (account && !rule.payeeKinds.includes(account.ownerKind)) throw new LedgerError('NL012', `a ${kind} transaction may not pay a ${account.ownerKind} account`); }
    if (kind !== 'fine') return;
    const total = credits.reduce((sum, leg) => sum + leg.amount, 0);
    const toGovernment = credits.filter((leg) => accounts.get(leg.account).ownerKind === 'government');
    const others = credits.filter((leg) => accounts.get(leg.account).ownerKind !== 'government');
    if (toGovernment.length !== 1) throw new LedgerError('NL012', 'a fine pays exactly one government account');
    if (meta.officer.startsWith('player:')) {
      const officer = meta.officer.slice(7);
      const due = fineShares(total).government;
      if (toGovernment[0].amount !== due) throw new LedgerError('NL012', `of a fine of ${total}, government is due ${due} and was given ${toGovernment[0].amount}`);
      if (others.some((leg) => { const a = accounts.get(leg.account); return a.ownerKind !== 'player' || a.ownerId !== officer; })) throw new LedgerError('NL012', 'the rest of a fine goes to the constable who made the arrest and to nobody else');
      if (debits.some((leg) => { const a = accounts.get(leg.account); return a.ownerKind === 'player' && a.ownerId === officer; })) throw new LedgerError('NL012', 'the arresting constable may not pay the fine');
    } else if (others.length) throw new LedgerError('NL012', 'a fine after an arrest by a police officer goes to government in full');
  }

  function post(scopes, mayDebitSystem, request) {
    const { key, kind, initiator, reason, legs, meta = {}, reverses = null } = request || {};
    if (typeof key !== 'string' || key.length < 8 || key.length > 200) {
      throw new LedgerError('NL005', 'idempotency key must be 8 to 200 characters');
    }
    if (!initiator || !reason) throw new LedgerError('NL005', 'initiator and reason are required');
    if (!Array.isArray(legs) || legs.length < 2 || legs.length > 64) {
      throw new LedgerError('NL005', 'a transaction needs 2 to 64 entries');
    }
    const seen = new Set();
    for (const leg of legs) {
      if (!leg || typeof leg.account !== 'string' || !Number.isSafeInteger(leg.amount) || leg.amount === 0) {
        throw new LedgerError('NL005', 'each entry needs an account and a non-zero whole-number amount');
      }
      if (seen.has(leg.account)) throw new LedgerError('NL005', 'an account may appear only once in a transaction');
      seen.add(leg.account);
    }
    const scope = LEDGER_KINDS[kind];
    if (!scope) throw new LedgerError('NL005', `unknown transaction kind ${kind}`);
    if (!scopes.includes(scope)) throw new LedgerError('NL004', `transaction kind ${kind} is not permitted for this role`);

    const hash = ledgerHash({ kind, initiator, reason, meta, legs, reverses });
    const previous = byKey.get(key);
    if (previous) {
      if (previous.hash !== hash) throw new LedgerError('NL002', `idempotency key ${key} was already used for a different request`);
      return { id: previous.id, replayed: true };
    }

    const sums = new Map();
    for (const leg of legs) {
      const account = accounts.get(leg.account);
      if (!account) throw new LedgerError('NL006', 'one or more accounts do not exist');
      const assetClass = LEDGER_ASSETS[account.asset].class;
      if (scope !== 'bridge' && assetClass !== scope) {
        throw new LedgerError('NL004', `a ${scope} transaction may not touch an account holding another value class`);
      }
      if (!mayDebitSystem && account.ownerKind === 'system' && leg.amount < 0) {
        throw new LedgerError('NL004', 'this role may not debit a system account');
      }
      sums.set(account.asset, (sums.get(account.asset) || 0) + leg.amount);
    }
    for (const [asset, sum] of sums) {
      if (sum !== 0) throw new LedgerError('NL003', `entries do not sum to zero for asset ${asset}`);
    }
    for (const leg of legs) {
      const account = accounts.get(leg.account);
      const after = account.balance + leg.amount;
      if (!Number.isSafeInteger(after)) throw new LedgerError('22003', 'balance out of range');
      if (!account.allowNegative && leg.amount < 0 && after < 0) {
        throw new LedgerError('NL001', `insufficient funds in account ${account.id}`);
      }
    }

    if (!reverses) checkKind(kind, meta, legs);

    // Everything checked: apply.
    const id = `txn-${String(transactions.length + 1).padStart(7, '0')}`;
    const entries = legs.map((leg, index) => {
      const account = accounts.get(leg.account);
      account.balance += leg.amount;
      account.entries += 1;
      return { line: index + 1, account: account.id, asset: account.asset, amount: leg.amount, balanceAfter: account.balance };
    });
    const txn = Object.freeze({
      id, seq: transactions.length + 1, key, hash, kind, initiator, reason, reverses,
      meta: Object.freeze({ ...meta }), at: clock(), entries: Object.freeze(entries.map(Object.freeze)),
    });
    transactions.push(txn);
    byKey.set(key, txn);
    if (!reverses) for (const subject of subjectsOf(kind, meta)) paidOnce.set(subject, id);
    return { id, replayed: false };
  }

  function balanceOf(allowedClasses, accountId) {
    const account = accounts.get(accountId);
    if (!account) throw new LedgerError('NL006', `account ${accountId} does not exist`);
    if (!allowedClasses.includes(LEDGER_ASSETS[account.asset].class)) {
      throw new LedgerError('NL004', 'this role may not read that account');
    }
    return account.balance;
  }

  function historyOf(allowedClasses, accountId, limit = 20) {
    balanceOf(allowedClasses, accountId);
    const rows = [];
    for (let i = transactions.length - 1; i >= 0 && rows.length < limit; i -= 1) {
      const txn = transactions[i];
      const mine = txn.entries.find((entry) => entry.account === accountId);
      if (mine) rows.push({ id: txn.id, kind: txn.kind, reason: txn.reason, at: txn.at, amount: mine.amount, balanceAfter: mine.balanceAfter, meta: txn.meta });
    }
    return rows;
  }

  function findAccount(ownerKind, ownerId, purpose, asset) {
    return byOwner.get(ownerKey(ownerKind, String(ownerId), purpose, asset)) || null;
  }

  function reconcile() {
    const problems = [];
    const sums = new Map();
    const running = new Map();
    for (const txn of transactions) {
      const perAsset = new Map();
      for (const entry of txn.entries) {
        perAsset.set(entry.asset, (perAsset.get(entry.asset) || 0) + entry.amount);
        sums.set(entry.account, (sums.get(entry.account) || 0) + entry.amount);
        running.set(entry.account, entry.balanceAfter);
      }
      for (const [asset, sum] of perAsset) {
        if (sum !== 0) problems.push({ check: 'transaction_not_zero_sum', subject: txn.id, detail: `${asset} sums to ${sum}` });
      }
    }
    const perAssetTotal = new Map();
    for (const account of accounts.values()) {
      const sum = sums.get(account.id) || 0;
      if (sum !== account.balance) problems.push({ check: 'balance_differs_from_entries', subject: account.id, detail: `${account.balance} vs ${sum}` });
      if (running.has(account.id) && running.get(account.id) !== account.balance) {
        problems.push({ check: 'running_balance_differs', subject: account.id, detail: '' });
      }
      if (account.balance < 0 && !account.allowNegative) problems.push({ check: 'negative_balance', subject: account.id, detail: String(account.balance) });
      perAssetTotal.set(account.asset, (perAssetTotal.get(account.asset) || 0) + account.balance);
    }
    for (const [asset, total] of perAssetTotal) {
      if (total !== 0) problems.push({ check: 'asset_not_conserved', subject: asset, detail: `balances sum to ${total}` });
    }
    return problems;
  }

  function supply() {
    const out = {};
    for (const account of accounts.values()) {
      if (account.allowNegative) out[account.asset] = (out[account.asset] || 0) - account.balance;
    }
    return out;
  }

  // Operator accounts. The two that may go negative mirror what is in circulation.
  const system = {
    issuance: addAccount('system', 'operator', 'issuance', 'TR', true),
    chainCustody: addAccount('system', 'operator', 'chain_custody', 'TBTC', true),
    conversionReserve: addAccount('system', 'operator', 'conversion_reserve', 'TBTC', false),
    withdrawalPending: addAccount('system', 'operator', 'withdrawal_pending', 'TBTC', false),
    revenue: addAccount('system', 'operator', 'revenue', 'TBTC', false),
    redemptionEscrow: addAccount('system', 'operator', 'redemption_escrow', 'TR', false),
  };

  if (saved) {
    for (const row of saved.accounts) {
      // an account from before the currency was renamed: the same account, the same number, the new name
      const asset = LEGACY_ASSET_CODES[row.asset] || row.asset;
      accounts.set(row.id, { ...row, asset });
      byOwner.set(ownerKey(row.ownerKind, row.ownerId, row.purpose, asset), row.id);
    }
    for (const row of saved.transactions) {
      const txn = Object.freeze({ ...row, meta: Object.freeze(row.meta), entries: Object.freeze(row.entries.map(Object.freeze)) });
      transactions.push(txn);
      byKey.set(txn.key, txn);
      if (!txn.reverses) for (const subject of subjectsOf(txn.kind, txn.meta)) paidOnce.set(subject, txn.id);
    }
  }

  const GAME = ['game'];
  const EXTERNAL = ['external'];
  return {
    system,
    setClock(fn) { clock = fn; },
    // The only handle the game simulation receives.
    gameplay: Object.freeze({
      post: (request) => post(['game'], false, request),
      openAccount: (ownerKind, ownerId, purpose) => open(GAME, ownerKind, ownerId, purpose, 'TR'),
      findAccount: (ownerKind, ownerId, purpose) => findAccount(ownerKind, ownerId, purpose, 'TR'),
      balance: (accountId) => balanceOf(GAME, accountId),
      history: (accountId, limit) => historyOf(GAME, accountId, limit),
    }),
    // Operator monetary authority: issues and retires game currency.
    monetary: Object.freeze({
      post: (request) => post(['game'], true, request),
      balance: (accountId) => balanceOf(GAME, accountId),
    }),
    // Settlement service: external assets and the bridge between classes.
    settlement: Object.freeze({
      post: (request) => post(['external', 'bridge'], true, request),
      openAccount: (ownerKind, ownerId, purpose, asset) => open(['external', 'game'], ownerKind, ownerId, purpose, asset),
      findAccount,
      balance: (accountId) => balanceOf(EXTERNAL, accountId),
      history: (accountId, limit) => historyOf(EXTERNAL, accountId, limit),
    }),
    auditor: Object.freeze({
      reconcile, supply,
      transactionCount: () => transactions.length,
      balance: (accountId) => balanceOf(['game', 'external'], accountId),
      transactions: () => transactions,
    }),
    serialize() {
      return { accounts: [...accounts.values()].map((a) => ({ ...a })), transactions: transactions.map((t) => ({ ...t, meta: { ...t.meta }, entries: t.entries.map((e) => ({ ...e })) })) };
    },
  };
}
